"""Shrink a file set until its token sum fits a hard cap."""

from dataclasses import dataclass

from contextpack.compress import compress
from contextpack.models import Compression
from contextpack.tokens import count_tokens

_NEXT: dict[str, Compression] = {
    "full": "skeleton",
    "skeleton": "outline",
}


@dataclass
class BudgetItem:
    relative_path: str
    size_bytes: int
    language: str
    raw: str
    mode: Compression
    pinned: bool
    variants: dict[str, str]
    content: str
    tokens: int


@dataclass
class BudgetFit:
    kept: list[BudgetItem]
    omitted: list[str]


def prepare_item(
    relative_path: str,
    size_bytes: int,
    language: str,
    raw: str,
    mode: Compression,
    pinned: bool,
) -> BudgetItem:
    variants = {
        "full": compress(raw, language, "full"),
        "skeleton": compress(raw, language, "skeleton"),
        "outline": compress(raw, language, "outline"),
    }
    content = variants[mode]
    return BudgetItem(
        relative_path=relative_path,
        size_bytes=size_bytes,
        language=language,
        raw=raw,
        mode=mode,
        pinned=pinned,
        variants=variants,
        content=content,
        tokens=count_tokens(content),
    )


def fit_budget(items: list[BudgetItem], max_tokens: int | None) -> BudgetFit:
    """Downgrade, then omit, until the token sum is within max_tokens.

    A pinned item is never changed. A ``None`` budget leaves every item alone.
    """
    kept = list(items)
    if max_tokens is None or max_tokens < 0:
        return BudgetFit(kept=kept, omitted=[])

    omitted: list[str] = []
    while _total(kept) > max_tokens:
        step = _best_downgrade(kept)
        if step is None:
            break
        item, new_mode = step
        item.mode = new_mode
        item.content = item.variants[new_mode]
        item.tokens = count_tokens(item.content)

    while _total(kept) > max_tokens:
        victims = [item for item in kept if not item.pinned]
        if not victims:
            break
        victim = min(victims, key=lambda item: (item.rank, -item.tokens, item.relative_path))
        kept.remove(victim)
        omitted.append(f"{victim.relative_path} (over-budget)")

    kept.sort(key=lambda item: item.relative_path)
    omitted.sort()
    return BudgetFit(kept=kept, omitted=omitted)


def _total(items: list[BudgetItem]) -> int:
    return sum(item.tokens for item in items)


def _best_downgrade(items: list[BudgetItem]) -> tuple[BudgetItem, Compression] | None:
    best: tuple[tuple[float, int, str], BudgetItem, Compression] | None = None
    for item in items:
        if item.pinned:
            continue
        nxt = _NEXT.get(item.mode)
        if nxt is None:
            continue
        saved = item.tokens - count_tokens(item.variants[nxt])
        key = (-item.rank, saved, item.relative_path)
        if best is None or key > best[0]:
            best = (key, item, nxt)
    if best is None:
        return None
    return best[1], best[2]


"""Pick full, skeleton, or outline text for one file."""

import pathspec

from contextpack.models import Compression, PackConfig
from contextpack.skeleton import outline, skeletonize

_MODES = {"full", "skeleton", "outline"}


def parse_rule(raw: str) -> tuple[str, Compression]:
    if "=" not in raw:
        raise ValueError(f"Rule must be PATTERN=MODE, got {raw!r}")
    pattern, mode = raw.rsplit("=", 1)
    pattern = pattern.strip()
    mode = mode.strip()
    if not pattern or mode not in _MODES:
        raise ValueError(f"Rule must be PATTERN=full|skeleton|outline, got {raw!r}")
    return pattern, mode  # type: ignore[return-value]


def _matches(patterns: list[str], relative: str) -> bool:
    if not patterns:
        return False
    spec = pathspec.PathSpec.from_lines("gitignore", patterns)
    return bool(spec.match_file(relative))


def mode_for(relative: str, config: PackConfig) -> Compression:
    for pattern, mode in (parse_rule(rule) for rule in config.rules):
        if _matches([pattern], relative):
            return mode
    if _matches(config.focus, relative):
        return "full"
    return config.mode

def is_focus_pinned(relative: str, config: PackConfig) -> bool:
    """True when focus, not a rule, is what selected this file's mode."""
    for pattern, _mode in (parse_rule(rule) for rule in config.rules):
        if _matches([pattern], relative):
            return False
    return _matches(config.focus, relative)


def compress(source: str, language: str, mode: Compression) -> str:
    if mode == "full":
        return source
    if mode == "skeleton":
        return skeletonize(source, language)
    return outline(source, language)

from pathlib import Path
import pathspec
# Directories and files that are never useful as model context. DEFAULT_EXCLUDES = [ ".git/", ".hg/", ".svn/", ".idea/", ".vscode/", "node_modules/", "vendor/", "dist/", "build/", "coverage/", ".next/", ".nuxt/", ".venv/", "venv/", "__pycache__/", ".pytest_cache/", ".mypy_cache/", ".ruff_cache/", "*.pyc", "*.pyo", "package-lock.json", "pnpm-lock.yaml", "yarn.lock", "bun.lock", "bun.lockb", "Cargo.lock", "poetry.lock", "Pipfile.lock", "composer.lock", "Gemfile.lock", ]
BINARY_SUFFIXES = { ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".bmp", ".svgz", ".pdf", ".zip", ".tar", ".gz", ".tgz", ".bz2", ".7z", ".rar", ".woff", ".woff2", ".ttf", ".eot", ".otf", ".mp3", ".mp4", ".mov", ".avi", ".webm", ".wav", ".exe", ".dll", ".so", ".dylib", ".bin", ".wasm", ".sqlite", ".db", ".parquet", ".class", ".jar", }
LANGUAGE_BY_SUFFIX = { ".py": "python", ".pyi": "python", ".js": "javascript", ".mjs": "javascript", ".cjs": "javascript", ".jsx": "jsx", ".ts": "typescript", ".tsx": "tsx", ".go": "go", ".rs": "rust", ".java": "java", ".kt": "kotlin", ".rb": "ruby", ".php": "php", ".cs": "csharp", ".c": "c", ".h": "c", ".cpp": "cpp", ".hpp": "cpp", ".swift": "swift", ".sql": "sql", ".sh": "bash", ".bash": "bash", ".zsh": "bash", ".json": "json", ".yaml": "yaml", ".yml": "yaml", ".toml": "toml", ".md": "markdown", ".html": "html", ".css": "css", ".scss": "scss", }
def language_for(path: Path) -> str: return LANGUAGE_BY_SUFFIX.get(path.suffix.lower(), "text")
def load_spec(root: Path, respect_gitignore: bool, extra: list[str]) -> pathspec.PathSpec: lines = list(DEFAULT_EXCLUDES) lines.extend(extra) if respect_gitignore: gitignore = root / ".gitignore" if gitignore.is_file(): lines.extend(gitignore.read_text(encoding="utf-8", errors="replace").splitlines()) return pathspec.PathSpec.from_lines("gitignore", lines)
def is_binary(path: Path) -> bool: if path.suffix.lower() in BINARY_SUFFIXES: return True try: sample = path.read_bytes()[:8192] except OSError: return True return b"\x00" in sample
def iter_source_files(root: Path, spec: pathspec.PathSpec, max_file_bytes: int): """Yield (absolute_path, relative_posix) for text files under root.
Skipped relative paths are yielded as the third value when the file is rejected. """ root = root.resolve() for path in root.rglob("*"): if not path.is_file(): continue relative = path.relative_to(root).as_posix() if spec.match_file(relative): yield None, relative, "ignored" continue try: size = path.stat().st_size except OSError: yield None, relative, "unreadable" continue if size > max_file_bytes: yield None, relative, f"oversize:{size}" continue if is_binary(path): yield None, relative, "binary" continue yield path, relative, None


"""Score files from static imports and entrypoint distance."""

import posixpath
import re
from collections import deque

import pathspec

DEFAULT_ENTRY_GLOBS = [
    "main.py",
    "__main__.py",
    "app.py",
    "manage.py",
    "wsgi.py",
    "asgi.py",
    "cli.py",
    "index.js",
    "index.ts",
    "index.tsx",
    "index.mjs",
    "main.js",
    "main.ts",
]

_PY_IMPORT = re.compile(r"(?m)^[ \t]*import[ \t]+([\w.]+)")
_PY_FROM = re.compile(r"(?m)^[ \t]*from[ \t]+(\.*)([\w.]*)[ \t]+import[ \t]+(.+)")
_JS_SPEC = re.compile(
    r"""(?:import|export)\s+(?:[^'"\n]+?\s+from\s+)?['"](\.[^'"]+)['"]|require\(\s*['"](\.[^'"]+)['"]\s*\)"""
)
_JS_EXTS = (
    "",
    ".ts",
    ".tsx",
    ".js",
    ".jsx",
    ".mjs",
    ".cjs",
    "/index.ts",
    "/index.tsx",
    "/index.js",
    "/index.jsx",
    "/index.mjs",
)

_UNREACHABLE = 10_000


def rank_paths(files: list[tuple[str, str, str]], entry_globs: list[str]) -> dict[str, float]:
    """Return a score per relative path. Higher means keep it fuller for longer."""
    known = {path for path, _raw, _lang in files}
    graph: dict[str, set[str]] = {path: set() for path in known}
    for path, raw, language in files:
        for dep in _imports(raw, language, path, known):
            graph[path].add(dep)

    spec = pathspec.PathSpec.from_lines("gitignore", [*DEFAULT_ENTRY_GLOBS, *entry_globs])
    distance: dict[str, int] = {}
    queue: deque[str] = deque()
    for path in sorted(known):
        if spec.match_file(path):
            distance[path] = 0
            queue.append(path)
    while queue:
        current = queue.popleft()
        for dep in sorted(graph[current]):
            if dep not in distance:
                distance[dep] = distance[current] + 1
                queue.append(dep)

    indegree = {path: 0 for path in known}
    for deps in graph.values():
        for dep in deps:
            indegree[dep] += 1

    return {
        path: float((_UNREACHABLE - distance.get(path, _UNREACHABLE)) * 100 + indegree[path])
        for path in known
    }


def _imports(raw: str, language: str, path: str, known: set[str]) -> set[str]:
    if language == "python":
        found = _python_imports(raw, path)
    elif language in {"javascript", "jsx", "typescript", "tsx"}:
        found = _js_imports(raw, path)
    else:
        return set()
    return {item for item in found if item in known}


def _python_imports(raw: str, path: str) -> set[str]:
    found: set[str] = set()
    for match in _PY_IMPORT.finditer(raw):
        found.update(_python_candidates(match.group(1).split(".")))
    for match in _PY_FROM.finditer(raw):
        dots, module, names = match.group(1), match.group(2), match.group(3)
        if dots:
            parts = path.split("/")[:-1]
            up = len(dots) - 1
            if up > len(parts):
                continue
            base = parts[: len(parts) - up]
            if module:
                base.extend(module.split("."))
            found.update(_python_candidates(base))
            if not module:
                for name in re.findall(r"[A-Za-z_]\w*", names.split("#", 1)[0]):
                    found.update(_python_candidates([*base, name]))
        else:
            pieces = module.split(".")
            found.update(_python_candidates(pieces))
            for name in re.findall(r"[A-Za-z_]\w*", names.split("#", 1)[0]):
                found.update(_python_candidates([*pieces, name]))
    return found


def _python_candidates(parts: list[str]) -> set[str]:
    if not parts:
        return set()
    stem = "/".join(parts)
    return {f"{stem}.py", f"{stem}/__init__.py"}


def _js_imports(raw: str, path: str) -> set[str]:
    found: set[str] = set()
    parent = posixpath.dirname(path)
    for match in _JS_SPEC.finditer(raw):
        spec = match.group(1) or match.group(2)
        if not spec:
            continue
        base = posixpath.normpath(posixpath.join(parent, spec))
        if base.startswith("../") or base == "..":
            continue
        for ext in _JS_EXTS:
            found.add(f"{base}{ext}")
    return found


"""Replace function and method bodies with placeholders. Signatures stay."""

from tree_sitter import Language, Node, Parser

import tree_sitter_javascript as tsjavascript
import tree_sitter_python as tspython
import tree_sitter_typescript as tstypescript

_PY = Language(tspython.language())
_JS = Language(tsjavascript.language())
_TS = Language(tstypescript.language_typescript())
_TSX = Language(tstypescript.language_tsx())

_PARSERS: dict[str, Parser] = {}

_JS_FUNCTION_TYPES = {
    "function_declaration",
    "generator_function_declaration",
    "function",
    "generator_function",
    "method_definition",
    "arrow_function",
}

_PY_SKIP_IN_BLOCK = {"indent", "dedent", "newline", "comment", "line_comment"}


def _parser(language: Language) -> Parser:
    try:
        return Parser(language)
    except TypeError:
        parser = Parser()
        parser.language = language
        return parser


def _parser_for(language_name: str) -> Parser | None:
    key = {
        "python": "python",
        "javascript": "javascript",
        "jsx": "javascript",
        "typescript": "typescript",
        "tsx": "tsx",
    }.get(language_name)
    if key is None:
        return None
    if key not in _PARSERS:
        lang = {"python": _PY, "javascript": _JS, "typescript": _TS, "tsx": _TSX}[key]
        _PARSERS[key] = _parser(lang)
    return _PARSERS[key]


def skeletonize(source: str, language_name: str) -> str:
    """Return source with implementation bodies removed.

    Languages without a grammar are returned unchanged.
    A parse that produces no tree returns the original source.
    """
    parser = _parser_for(language_name)
    if parser is None or not source:
        return source
    raw = source.encode("utf-8")
    tree = parser.parse(raw)
    if tree.root_node.has_error and tree.root_node.child_count == 0:
        return source

    if language_name == "python":
        spans = _python_spans(tree.root_node, raw)
    else:
        spans = _js_spans(tree.root_node, raw)

    if not spans:
        return source
    return _apply(raw, _drop_nested(spans)).decode("utf-8", errors="replace")


def _python_spans(root: Node, source: bytes) -> list[tuple[int, int, bytes]]:
    spans: list[tuple[int, int, bytes]] = []

    def walk(node: Node) -> None:
        if node.type == "function_definition":
            body = node.child_by_field_name("body")
            if body is not None and body.type == "block":
                span = _python_block_span(body, source)
                if span is not None:
                    spans.append(span)
        for child in node.children:
            walk(child)

    walk(root)
    return spans


def _python_block_span(block: Node, source: bytes) -> tuple[int, int, bytes] | None:
    statements = [child for child in block.children if child.type not in _PY_SKIP_IN_BLOCK]
    if not statements:
        return None

    start_stmt = statements[0]
    if _is_docstring(start_stmt) and len(statements) > 1:
        start_stmt = statements[1]
    elif _is_docstring(start_stmt):
        return None

    if len(statements) == 1 and start_stmt.type == "expression_statement":
        only = start_stmt.child_by_field_name("expression") or (
            start_stmt.children[0] if start_stmt.child_count else None
        )
        if only is not None and only.type == "ellipsis":
            return None

    indent = _line_indent(source, start_stmt.start_byte)
    return (start_stmt.start_byte, statements[-1].end_byte, indent + b"...")


def _is_docstring(node: Node) -> bool:
    if node.type != "expression_statement":
        return False
    expr = node.child_by_field_name("expression")
    if expr is None and node.child_count:
        expr = node.children[0]
    return expr is not None and expr.type == "string"


def _js_spans(root: Node, source: bytes) -> list[tuple[int, int, bytes]]:
    spans: list[tuple[int, int, bytes]] = []

    def walk(node: Node) -> None:
        if node.type in _JS_FUNCTION_TYPES:
            body = node.child_by_field_name("body")
            if body is not None:
                span = _js_body_span(node, body)
                if span is not None:
                    spans.append(span)
                    return
        for child in node.children:
            walk(child)

    walk(root)
    return spans


def _js_body_span(fn: Node, body: Node) -> tuple[int, int, bytes] | None:
    if body.type == "statement_block":
        if body.end_byte - body.start_byte <= len(b"{ /* ... */ }"):
            text = body.text or b""
            if b"/* ... */" in text:
                return None
        return (body.start_byte, body.end_byte, b"{ /* ... */ }")
    if fn.type == "arrow_function":
        return (body.start_byte, body.end_byte, b"{ /* ... */ }")
    return None


def _line_indent(source: bytes, index: int) -> bytes:
    line_start = source.rfind(b"\n", 0, index) + 1
    prefix = source[line_start:index]
    indent = prefix[: len(prefix) - len(prefix.lstrip(b" \t"))]
    return indent


def _drop_nested(spans: list[tuple[int, int, bytes]]) -> list[tuple[int, int, bytes]]:
    ordered = sorted(spans, key=lambda item: (item[0], -(item[1] - item[0])))
    kept: list[tuple[int, int, bytes]] = []
    for start, end, repl in ordered:
        if any(prev_s <= start and end <= prev_e for prev_s, prev_e, _ in kept):
            continue
        kept.append((start, end, repl))
    return kept


def _apply(source: bytes, spans: list[tuple[int, int, bytes]]) -> bytes:
    out = bytearray(source)
    for start, end, repl in sorted(spans, key=lambda item: item[0], reverse=True):
        out[start:end] = repl
    return bytes(out)


def outline(source: str, language_name: str) -> str:
    """Imports plus class and function signatures. No bodies and no docstrings."""
    parser = _parser_for(language_name)
    if parser is None or not source:
        return source
    raw = source.encode("utf-8")
    tree = parser.parse(raw)
    if language_name == "python":
        lines = _python_outline(tree.root_node, raw, 0)
    else:
        lines = _js_outline(tree.root_node, raw, 0)
    if not lines:
        return source
    return "\n".join(lines) + "\n"


def _signature_until(node: Node, source: bytes, body: Node | None) -> str:
    end = body.start_byte if body is not None else node.end_byte
    text = source[node.start_byte:end].decode("utf-8", errors="replace").strip()
    if text.endswith(":"):
        text = text[:-1].rstrip()
    if text.endswith("{"):
        text = text[:-1].rstrip()
    if text.endswith("=>"):
        text = text[:-2].rstrip()
    return " ".join(text.split())


def _python_outline(node: Node, source: bytes, indent: int) -> list[str]:
    lines: list[str] = []
    pad = "    " * indent
    for child in node.children:
        target = child
        decorators: list[str] = []
        if child.type == "decorated_definition":
            for part in child.children:
                if part.type == "decorator":
                    decorators.append(source[part.start_byte:part.end_byte].decode("utf-8", errors="replace").strip())
                elif part.type in {"function_definition", "class_definition"}:
                    target = part
        if target.type in {"import_statement", "import_from_statement", "future_import_statement"} and indent == 0:
            text = source[target.start_byte:target.end_byte].decode("utf-8", errors="replace").strip()
            lines.append(text)
            continue
        if target.type == "class_definition":
            for deco in decorators:
                lines.append(f"{pad}{deco}")
            name = target.child_by_field_name("name")
            superclasses = target.child_by_field_name("superclasses")
            header = source[name.start_byte:name.end_byte].decode() if name else "Class"
            if superclasses is not None:
                bases = source[superclasses.start_byte:superclasses.end_byte].decode("utf-8", errors="replace")
                header = f"{header}{bases}"
            lines.append(f"{pad}class {header}:")
            body = target.child_by_field_name("body")
            if body is not None:
                lines.extend(_python_outline(body, source, indent + 1))
            continue
        if target.type == "function_definition":
            for deco in decorators:
                lines.append(f"{pad}{deco}")
            prefix = "async def" if any(part.type == "async" for part in target.children) else "def"
            name = target.child_by_field_name("name")
            params = target.child_by_field_name("parameters")
            returns = target.child_by_field_name("return_type")
            title = source[name.start_byte:name.end_byte].decode() if name else "fn"
            sig = source[params.start_byte:params.end_byte].decode() if params else "()"
            returns = target.child_by_field_name("return_type")
            if returns is not None:
                ret = source[returns.start_byte:returns.end_byte].decode("utf-8", errors="replace").strip()
                if not ret.startswith("->"):
                    ret = f"-> {ret}"
                sig = f"{sig} {ret}"
            lines.append(f"{pad}{prefix} {title}{sig}: ...")
    return lines


def _js_outline(node: Node, source: bytes, indent: int) -> list[str]:
    lines: list[str] = []
    pad = "  " * indent
    for child in node.children:
        if child.type == "import_statement" and indent == 0:
            text = source[child.start_byte:child.end_byte].decode("utf-8", errors="replace").strip()
            lines.append(" ".join(text.split()))
            continue
        if child.type in {"class_declaration", "class"}:
            lines.extend(_js_class(child, source, indent))
            continue
        if child.type in _JS_FUNCTION_TYPES:
            lines.extend(_js_signature_line(child, source, indent))
            continue
        if child.type == "export_statement":
            lines.extend(_js_outline(child, source, indent))
            continue
        if child.type in {"lexical_declaration", "variable_declaration"}:
            arrows = [desc for desc in child.children if desc.type == "variable_declarator"]
            for declarator in arrows:
                value = declarator.child_by_field_name("value")
                name = declarator.child_by_field_name("name")
                if value is None or name is None:
                    continue
                if value.type in {"arrow_function", "function", "generator_function", "class"}:
                    kind = "const"
                    prefix = source[child.start_byte:name.start_byte].decode("utf-8", errors="replace")
                    prefix = " ".join(prefix.split())
                    title = source[name.start_byte:name.end_byte].decode("utf-8", errors="replace")
                    lines.append(f"{pad}{prefix} {title} = ...")
                elif value.type == "call_expression":
                    continue
    return lines


def _js_class(node: Node, source: bytes, indent: int) -> list[str]:
    pad = "  " * indent
    body = node.child_by_field_name("body")
    header = _signature_until(node, source, body)
    lines = [f"{pad}{header} {{"]
    if body is not None:
        for child in body.children:
            if child.type in _JS_FUNCTION_TYPES or child.type in {"method_signature", "abstract_method_signature", "public_field_definition"}:
                if child.type == "public_field_definition":
                    text = source[child.start_byte:child.end_byte].decode("utf-8", errors="replace").strip()
                    lines.append(f"{'  ' * (indent + 1)}{text}")
                else:
                    lines.extend(_js_signature_line(child, source, indent + 1))
    lines.append(f"{pad}}}")
    return lines


def _js_signature_line(node: Node, source: bytes, indent: int) -> list[str]:
    body = node.child_by_field_name("body")
    header = _signature_until(node, source, body)
    if not header:
        return []
    return [f"{'  ' * indent}{header}"]


def _walk_limited(node: Node):
    yield node
    for child in node.children:
        yield from _walk_limited(child)


def _wrapper(export_node: Node, inner: Node) -> Node:
    """Outline uses the export node only to recover leading keywords; inner carries the body."""
    return inner if inner.type in {"class_declaration", "class", *_JS_FUNCTION_TYPES} else export_node


import tiktoken

_ENCODER = tiktoken.get_encoding("cl100k_base")


def count_tokens(text: str) -> int:
    if not text:
        return 0
    return len(_ENCODER.encode(text, disallowed_special=()))


from contextpack.cli import app

if __name__ == "__main__":
    app()
